/**
 * Site-wide search for The Apostles' Church website.
 *
 * Include on every page (after assets/js/search-index.js):
 *     <link rel="stylesheet" href="assets/css/site-search.css">
 *     <script src="assets/js/search-index.js" defer></script>
 *     <script src="assets/js/site-search.js" defer></script>
 *
 * It adds a "Search" button to the header (.main-nav), and opens a command-
 * palette style dialog with Ctrl/Cmd+K or "/". Results come from
 * window.APCH_SEARCH_INDEX, generated by tools/build-search-index.js.
 */
(function () {
    'use strict';

    if (window.__apchSiteSearch) return;
    window.__apchSiteSearch = true;

    var scriptEl = document.currentScript;
    var SITE_ROOT = scriptEl ? new URL('../../', scriptEl.src) : new URL('./', location.href);
    var RECENT_KEY = 'apch-recent-searches';
    var MAX_RESULTS = 40;
    var IS_MAC = /Mac|iPhone|iPad/.test(navigator.platform || navigator.userAgent);

    var CATEGORY_ICONS = {
        'Home': 'bx-home-alt',
        'About Us': 'bx-info-circle',
        'Community': 'bx-group',
        'Faith & Beliefs': 'bx-book-bookmark',
        'Resources': 'bx-book-open',
        'Digital Library': 'bx-library',
        'Giving': 'bx-donate-heart',
        'News': 'bx-news',
        'Store': 'bx-store'
    };

    var POPULAR = ['Articles of Faith', 'Baptism', 'Prayer', 'Marriage', 'Youth', 'Giving', 'History'];
    var QUICK_LINKS = ['articles.html', 'about.html', 'resources.html', 'membership.html', 'giving.html', 'news.html'];

    // ---------------------------------------------------------------- helpers
    function normalize(str) {
        return String(str || '')
            .toLowerCase()
            .normalize('NFD').replace(/[̀-ͯ]/g, '')
            .replace(/[‘’ʼ`]/g, "'")
            .replace(/[“”]/g, '"');
    }

    function tokenize(query) {
        return normalize(query)
            .split(/[^a-z0-9']+/)
            .map(function (t) { return t.replace(/^'+|'+$/g, ''); })
            // Single letters match almost everything; keep them only as digits.
            .filter(function (t) { return t.length > 1 || /\d/.test(t); });
    }

    function escapeHtml(str) {
        return String(str).replace(/[&<>"']/g, function (c) {
            return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
        });
    }

    function escapeRegExp(str) {
        return str.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    }

    function highlight(text, tokens) {
        var safe = escapeHtml(text);
        if (!tokens.length) return safe;
        var parts = tokens
            .slice()
            .sort(function (a, b) { return b.length - a.length; })
            .map(function (t) { return escapeRegExp(escapeHtml(t)); });
        return safe.replace(new RegExp('(' + parts.join('|') + ')', 'gi'), '<mark>$1</mark>');
    }

    function excerpt(text, tokens, size) {
        size = size || 170;
        if (!text) return '';
        if (text.length <= size) return text;
        var lower = normalize(text);
        var at = -1;
        tokens.forEach(function (t) {
            var i = lower.indexOf(t);
            if (i !== -1 && (at === -1 || i < at)) at = i;
        });
        if (at < 60) return text.slice(0, size).replace(/\s+\S*$/, '') + '…';
        var start = text.lastIndexOf(' ', at - 50);
        start = start < 0 ? 0 : start + 1;
        var out = text.slice(start, start + size).replace(/\s+\S*$/, '');
        return '…' + out + (start + size < text.length ? '…' : '');
    }

    function samePage(url) {
        var a = url.pathname.replace(/\/index\.html$/, '/');
        var b = location.pathname.replace(/\/index\.html$/, '/');
        return decodeURIComponent(a) === decodeURIComponent(b);
    }

    function storage(fn, fallback) {
        try { return fn(window.localStorage); } catch (e) { return fallback; }
    }

    // ------------------------------------------------------------ the index
    var entries = null;

    function buildEntries() {
        var pages = window.APCH_SEARCH_INDEX || [];
        var list = [];
        pages.forEach(function (page) {
            var url = new URL(page.u, SITE_ROOT);
            var current = samePage(url);
            var firstText = page.s.length ? page.s[0].t : '';
            list.push({
                kind: 'page',
                title: page.t,
                path: page.c,
                category: page.c,
                text: page.d || firstText,
                url: url,
                anchor: '',
                current: current,
                n: { title: normalize(page.t), path: normalize(page.c), text: normalize((page.d || '') + ' ' + firstText) }
            });
            page.s.forEach(function (s, i) {
                if (i === 0 && normalize(s.h) === normalize(page.t)) return;
                list.push({
                    kind: 'section',
                    title: s.h,
                    path: page.t,
                    category: page.c,
                    text: s.t,
                    url: url,
                    anchor: s.a,
                    current: current,
                    n: { title: normalize(s.h), path: normalize(page.t + ' ' + page.c), text: normalize(s.t) }
                });
            });
        });
        return list;
    }

    function scoreEntry(entry, tokens, phrase) {
        var n = entry.n;
        var score = 0;
        for (var i = 0; i < tokens.length; i++) {
            var t = tokens[i];
            var wordStart = new RegExp('(^|[^a-z0-9])' + escapeRegExp(t));
            var s = 0;
            if (n.title.indexOf(t) !== -1) s = wordStart.test(n.title) ? 12 : 7;
            else if (n.path.indexOf(t) !== -1) s = 4;
            else if (n.text.indexOf(t) !== -1) s = wordStart.test(n.text) ? 2.5 : 1.5;
            if (!s) return 0; // every word must match somewhere
            score += s;
        }
        if (tokens.length > 1) {
            if (n.title.indexOf(phrase) !== -1) score += 15;
            else if (n.text.indexOf(phrase) !== -1) score += 5;
        }
        if (n.title === phrase) score += 20;
        if (entry.kind === 'page') score += 3;
        if (entry.current) score += 1;
        return score;
    }

    function search(query) {
        if (!entries) entries = buildEntries();
        var tokens = tokenize(query);
        if (!tokens.length) return { tokens: tokens, results: [] };
        var phrase = tokens.join(' ');
        var results = [];
        entries.forEach(function (entry) {
            var score = scoreEntry(entry, tokens, phrase);
            if (score > 0) results.push({ entry: entry, score: score });
        });
        results.sort(function (a, b) { return b.score - a.score; });
        return { tokens: tokens, results: results.slice(0, MAX_RESULTS) };
    }

    function hrefFor(entry) {
        var url = new URL(entry.url.href);
        if (entry.anchor) {
            url.hash = entry.anchor;
        } else if (entry.kind === 'section') {
            // Text fragment: supporting browsers scroll to and highlight the heading.
            url.hash = ':~:text=' + encodeURIComponent(entry.title).replace(/-/g, '%2D');
        }
        return url.href;
    }

    // --------------------------------------------------------------- the UI
    var overlay, input, clearBtn, body, live, countEl, lastFocus;
    var activeIndex = -1;
    var optionEls = [];
    var debounceTimer = null;

    function buildTrigger() {
        // Retire the old per-page search buttons and modals.
        var legacy = document.querySelectorAll('#searchTrigger, a[href="#search"], [data-site-search]');
        Array.prototype.forEach.call(legacy, function (el) {
            var parent = el.parentElement;
            el.remove();
            if (parent && parent.classList.contains('utility-links') && !parent.children.length) parent.remove();
        });
        var oldModal = document.getElementById('searchModal');
        if (oldModal) oldModal.remove();

        var host = document.querySelector('.main-nav') || document.querySelector('header nav') || document.querySelector('header');
        var trigger = document.createElement('button');
        trigger.type = 'button';
        trigger.className = 'site-search-trigger';
        trigger.setAttribute('aria-label', 'Search the site');
        trigger.setAttribute('aria-haspopup', 'dialog');
        trigger.innerHTML =
            "<i class='bx bx-search' aria-hidden='true'></i>" +
            '<span class="ss-trigger-label">Search</span>' +
            '<kbd aria-hidden="true">' + (IS_MAC ? '⌘' : 'Ctrl') + ' K</kbd>';
        trigger.addEventListener('click', function () { open(); });

        if (host) {
            host.appendChild(trigger);
        } else {
            trigger.style.cssText = 'position:fixed;top:1rem;right:1rem;z-index:9999;background:#2c7a3e;';
            document.body.appendChild(trigger);
        }
    }

    function buildDialog() {
        overlay = document.createElement('div');
        overlay.className = 'ss-overlay';
        overlay.setAttribute('role', 'dialog');
        overlay.setAttribute('aria-modal', 'true');
        overlay.setAttribute('aria-label', 'Search the site');
        overlay.hidden = true;
        overlay.innerHTML =
            '<div class="ss-panel">' +
            '  <form class="ss-form" role="search" autocomplete="off">' +
            "    <i class='bx bx-search' aria-hidden='true'></i>" +
            '    <label class="ss-sr-only" for="ss-input">Search the site</label>' +
            '    <input id="ss-input" class="ss-input" type="search" placeholder="Search pages, teachings, resources…"' +
            '           role="combobox" aria-autocomplete="list" aria-expanded="false" aria-controls="ss-listbox" spellcheck="false" enterkeyhint="search">' +
            '    <button type="button" class="ss-clear" aria-label="Clear search" hidden><i class="bx bx-x-circle" aria-hidden="true"></i></button>' +
            '    <button type="button" class="ss-close" aria-label="Close search"><span class="ss-close-text">ESC</span><i class="bx bx-x ss-close-icon" aria-hidden="true"></i></button>' +
            '  </form>' +
            '  <div class="ss-body" id="ss-listbox" role="listbox" aria-label="Search results"></div>' +
            '  <div class="ss-footer">' +
            '    <div class="ss-keys" aria-hidden="true">' +
            '      <span><kbd>↑</kbd><kbd>↓</kbd> to navigate</span>' +
            '      <span><kbd>↵</kbd> to open</span>' +
            '      <span><kbd>esc</kbd> to close</span>' +
            '    </div>' +
            '    <span class="ss-count"></span>' +
            '  </div>' +
            '  <div class="ss-sr-only" aria-live="polite" aria-atomic="true"></div>' +
            '</div>';
        document.body.appendChild(overlay);

        input = overlay.querySelector('.ss-input');
        clearBtn = overlay.querySelector('.ss-clear');
        body = overlay.querySelector('.ss-body');
        live = overlay.querySelector('[aria-live]');
        countEl = overlay.querySelector('.ss-count');

        overlay.addEventListener('mousedown', function (e) {
            if (e.target === overlay) close();
        });
        overlay.querySelector('.ss-close').addEventListener('click', function () { close(); });
        overlay.querySelector('.ss-form').addEventListener('submit', function (e) {
            e.preventDefault();
            activate(activeIndex >= 0 ? activeIndex : 0, false);
        });
        clearBtn.addEventListener('click', function () {
            input.value = '';
            render();
            input.focus();
        });
        input.addEventListener('input', function () {
            clearTimeout(debounceTimer);
            debounceTimer = setTimeout(render, 60);
        });
        input.addEventListener('keydown', onInputKey);
        overlay.addEventListener('keydown', trapFocus);
        body.addEventListener('mousemove', function (e) {
            var opt = e.target.closest('.ss-result');
            if (opt) setActive(optionEls.indexOf(opt), false);
        });
        body.addEventListener('click', function (e) {
            var chip = e.target.closest('.ss-chip');
            if (chip) {
                input.value = chip.getAttribute('data-query');
                render();
                input.focus();
                return;
            }
            var opt = e.target.closest('.ss-result');
            if (!opt) return;
            if (e.ctrlKey || e.metaKey || e.shiftKey || e.button === 1) return; // let the browser open a new tab
            e.preventDefault();
            activate(optionEls.indexOf(opt), false);
        });
    }

    function resultHtml(entry, tokens, id) {
        var icon = entry.kind === 'section' ? 'bx-hash' : (CATEGORY_ICONS[entry.category] || 'bx-file');
        var path = entry.kind === 'section' && entry.path !== entry.category
            ? entry.category + ' › ' + entry.path
            : entry.category;
        return '<a class="ss-result" role="option" aria-selected="false" id="' + id + '" href="' + escapeHtml(hrefFor(entry)) + '">' +
            "<span class='ss-result-icon' aria-hidden='true'><i class='bx " + icon + "'></i></span>" +
            '<span class="ss-result-main">' +
            '<span class="ss-result-title">' + highlight(entry.title, tokens) + '</span>' +
            '<span class="ss-result-path">' + escapeHtml(path) + '</span>' +
            (entry.text ? '<span class="ss-result-snippet">' + highlight(excerpt(entry.text, tokens), tokens) + '</span>' : '') +
            '</span>' +
            "<i class='bx bx-right-arrow-alt ss-result-go' aria-hidden='true'></i>" +
            '</a>';
    }

    function groupHtml(label, items, tokens, offset) {
        var gid = 'ss-g-' + offset;
        return '<div role="group" aria-labelledby="' + gid + '">' +
            '<p class="ss-group-label" id="' + gid + '">' + escapeHtml(label) + '</p>' +
            items.map(function (entry, i) { return resultHtml(entry, tokens, 'ss-opt-' + (offset + i)); }).join('') +
            '</div>';
    }

    function renderStart() {
        if (!entries) entries = buildEntries();
        var recent = storage(function (s) { return JSON.parse(s.getItem(RECENT_KEY) || '[]'); }, []);
        var html = '';
        if (recent.length) {
            html += '<p class="ss-group-label">Recent searches</p><div class="ss-chips">' +
                recent.map(function (q) {
                    return "<button type='button' class='ss-chip' data-query='" + escapeHtml(q) + "'><i class='bx bx-history' aria-hidden='true'></i>" + escapeHtml(q) + '</button>';
                }).join('') + '</div>';
        }
        html += '<p class="ss-group-label">Popular topics</p><div class="ss-chips">' +
            POPULAR.map(function (q) {
                return "<button type='button' class='ss-chip' data-query='" + escapeHtml(q) + "'><i class='bx bx-trending-up' aria-hidden='true'></i>" + escapeHtml(q) + '</button>';
            }).join('') + '</div>';

        var quick = QUICK_LINKS.map(function (u) {
            var href = new URL(u, SITE_ROOT).href;
            return entries.filter(function (e) { return e.kind === 'page' && e.url.href === href; })[0];
        }).filter(Boolean);
        if (quick.length) html += groupHtml('Quick links', quick, [], 0);

        body.innerHTML = html;
        countEl.textContent = (window.APCH_SEARCH_INDEX || []).length + ' pages searchable';
        finishRender(quick.length ? 0 : -1);
    }

    function render() {
        var query = input.value;
        clearBtn.hidden = !query;
        if (!query.trim()) {
            renderStart();
            live.textContent = '';
            return;
        }

        var found = search(query);
        if (!found.tokens.length) {
            body.innerHTML = '<div class="ss-empty"><i class="bx bx-edit-alt" aria-hidden="true"></i>' +
                '<strong>Keep typing…</strong><p>Enter at least two letters to search.</p></div>';
            countEl.textContent = '';
            live.textContent = '';
            finishRender(-1);
            return;
        }
        if (!found.results.length) {
            body.innerHTML = '<div class="ss-empty"><i class="bx bx-search-alt" aria-hidden="true"></i>' +
                '<strong>No results for “' + escapeHtml(query.trim()) + '”</strong>' +
                '<p>Check the spelling or try a broader word, such as “faith” or “prayer”.</p></div>';
            countEl.textContent = '0 results';
            live.textContent = 'No results';
            finishRender(-1);
            return;
        }

        // Groups appear in order of their best match (results are already sorted).
        var groups = [];
        var byLabel = {};
        found.results.forEach(function (r) {
            var label = r.entry.current && r.entry.kind === 'section' ? 'On this page' : r.entry.category;
            if (!byLabel[label]) {
                byLabel[label] = { label: label, items: [] };
                groups.push(byLabel[label]);
            }
            byLabel[label].items.push(r.entry);
        });
        var html = '';
        var offset = 0;
        groups.forEach(function (g) {
            html += groupHtml(g.label, g.items, found.tokens, offset);
            offset += g.items.length;
        });
        body.innerHTML = html;

        var n = found.results.length;
        countEl.textContent = n + (n === MAX_RESULTS ? '+' : '') + (n === 1 ? ' result' : ' results');
        live.textContent = countEl.textContent;
        finishRender(0);
    }

    function finishRender(initialActive) {
        optionEls = Array.prototype.slice.call(body.querySelectorAll('.ss-result'));
        input.setAttribute('aria-expanded', optionEls.length ? 'true' : 'false');
        body.scrollTop = 0;
        setActive(initialActive, false);
    }

    function setActive(index, scroll) {
        if (activeIndex >= 0 && optionEls[activeIndex]) {
            optionEls[activeIndex].classList.remove('is-active');
            optionEls[activeIndex].setAttribute('aria-selected', 'false');
        }
        activeIndex = index;
        var el = optionEls[index];
        if (!el) {
            activeIndex = -1;
            input.removeAttribute('aria-activedescendant');
            return;
        }
        el.classList.add('is-active');
        el.setAttribute('aria-selected', 'true');
        input.setAttribute('aria-activedescendant', el.id);
        if (scroll) el.scrollIntoView({ block: 'nearest' });
    }

    function onInputKey(e) {
        if (e.key === 'ArrowDown' || e.key === 'ArrowUp') {
            if (!optionEls.length) return;
            e.preventDefault();
            var step = e.key === 'ArrowDown' ? 1 : -1;
            var next = activeIndex < 0 ? (step > 0 ? 0 : optionEls.length - 1) : (activeIndex + step + optionEls.length) % optionEls.length;
            setActive(next, true);
        } else if (e.key === 'Enter') {
            e.preventDefault();
            if (activeIndex >= 0) activate(activeIndex, e.ctrlKey || e.metaKey);
        } else if (e.key === 'Home' && optionEls.length && e.ctrlKey) {
            e.preventDefault();
            setActive(0, true);
        } else if (e.key === 'End' && optionEls.length && e.ctrlKey) {
            e.preventDefault();
            setActive(optionEls.length - 1, true);
        }
    }

    function trapFocus(e) {
        if (e.key === 'Escape') {
            e.preventDefault();
            if (input.value) {
                input.value = '';
                render();
                input.focus();
            } else {
                close();
            }
            return;
        }
        if (e.key !== 'Tab') return;
        var focusable = Array.prototype.filter.call(
            overlay.querySelectorAll('input, button:not([hidden]), a[href]'),
            function (el) { return el.offsetParent !== null; }
        );
        if (!focusable.length) return;
        var first = focusable[0];
        var last = focusable[focusable.length - 1];
        if (e.shiftKey && document.activeElement === first) {
            e.preventDefault();
            last.focus();
        } else if (!e.shiftKey && document.activeElement === last) {
            e.preventDefault();
            first.focus();
        }
    }

    function remember(query) {
        query = query.trim();
        if (query.length < 2) return;
        storage(function (s) {
            var list = JSON.parse(s.getItem(RECENT_KEY) || '[]').filter(function (q) {
                return q.toLowerCase() !== query.toLowerCase();
            });
            list.unshift(query);
            s.setItem(RECENT_KEY, JSON.stringify(list.slice(0, 5)));
        });
    }

    function activate(index, newTab) {
        var el = optionEls[index];
        if (!el) return;
        remember(input.value);
        var href = el.getAttribute('href');
        if (newTab) {
            window.open(href, '_blank', 'noopener');
            return;
        }
        var url = new URL(href);
        if (samePage(url)) {
            close(true);
            scrollToTarget(url);
        } else {
            location.href = href;
        }
    }

    function headerOffset() {
        var header = document.querySelector('.main-header') || document.querySelector('header');
        var h = 0;
        if (header) {
            var pos = getComputedStyle(header).position;
            if (pos === 'sticky' || pos === 'fixed') h = header.getBoundingClientRect().height;
        }
        return h + 20;
    }

    function findTarget(url) {
        var hash = decodeURIComponent(url.hash.slice(1));
        if (!hash) return null;
        if (hash.indexOf(':~:text=') === 0) {
            var text = normalize(hash.slice(8));
            var heads = document.querySelectorAll('h1, h2, h3');
            for (var i = 0; i < heads.length; i++) {
                if (normalize(heads[i].textContent).replace(/\s+/g, ' ').trim() === text) return heads[i];
            }
            return null;
        }
        return document.getElementById(hash);
    }

    function scrollToTarget(url) {
        var target = findTarget(url);
        if (!target) {
            window.scrollTo({ top: 0, behavior: 'smooth' });
            return;
        }
        // Reveal the target if a page filter has hidden it (e.g. resources.html categories).
        var hidden = target.closest('.is-hidden');
        if (hidden) {
            var allBtn = document.querySelector('.category-btn[data-category="all"]');
            if (allBtn) allBtn.click();
        }
        var top = target.getBoundingClientRect().top + window.pageYOffset - headerOffset();
        window.scrollTo({ top: Math.max(0, top), behavior: 'smooth' });
        if (target.id && history.replaceState) history.replaceState(null, '', '#' + target.id);
        target.classList.remove('ss-target-flash');
        void target.offsetWidth;
        target.classList.add('ss-target-flash');
        setTimeout(function () { target.classList.remove('ss-target-flash'); }, 2400);
        if (!target.hasAttribute('tabindex')) target.setAttribute('tabindex', '-1');
        target.focus({ preventScroll: true });
    }

    function open(initialQuery) {
        if (!overlay) buildDialog();
        if (overlay.classList.contains('is-open')) {
            input.select();
            return;
        }
        lastFocus = document.activeElement;
        overlay.hidden = false;
        if (typeof initialQuery === 'string') input.value = initialQuery;
        render();
        // Force a reflow so the opening transition runs.
        void overlay.offsetWidth;
        overlay.classList.add('is-open');
        document.body.classList.add('ss-locked');
        input.focus();
        input.select();
    }

    function close(skipFocusRestore) {
        if (!overlay || !overlay.classList.contains('is-open')) return;
        overlay.classList.remove('is-open');
        document.body.classList.remove('ss-locked');
        setTimeout(function () {
            if (!overlay.classList.contains('is-open')) overlay.hidden = true;
        }, 220);
        if (!skipFocusRestore && lastFocus && lastFocus.focus) lastFocus.focus();
    }

    function isTyping(el) {
        if (!el) return false;
        var tag = el.tagName;
        return tag === 'INPUT' || tag === 'TEXTAREA' || tag === 'SELECT' || el.isContentEditable;
    }

    function onGlobalKey(e) {
        var key = (e.key || '').toLowerCase();
        if ((e.ctrlKey || e.metaKey) && !e.altKey && key === 'k') {
            e.preventDefault();
            open();
        } else if (key === '/' && !e.ctrlKey && !e.metaKey && !e.altKey && !isTyping(document.activeElement)) {
            if (overlay && overlay.classList.contains('is-open')) return;
            e.preventDefault();
            open();
        }
    }

    function init() {
        buildTrigger();
        document.addEventListener('keydown', onGlobalKey);
        var q = new URLSearchParams(location.search).get('q');
        if (q) open(q);
    }

    window.APCHSearch = { open: open, close: close, search: search };

    if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init);
    else init();
})();
